/* Enforce hidden attribute per specification */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1a24;
  --color-card: #28283a;
  --color-dark: #0f0f15;
  --color-work: #ff5964;
  --color-rest: #35a7ff;
  --color-text: #fffcf9;
  --color-accent: #f8c537;
  --font-main: 'Courier New', Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-main);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.timer-header {
  text-align: center;
}

.title {
  font-size: 28px;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-dark);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 14px;
  opacity: 0.85;
  letter-spacing: 1px;
}

.screen-card {
  width: 100%;
  background-color: var(--color-card);
  border: 4px solid var(--color-dark);
  box-shadow: 6px 6px 0px var(--color-dark);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.view-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.status-bar {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.badge {
  font-size: 16px;
  font-weight: bold;
  padding: 6px 12px;
  border: 3px solid var(--color-dark);
  background-color: var(--color-dark);
  color: var(--color-text);
  box-shadow: 2px 2px 0px var(--color-dark);
}

.phase-work {
  background-color: var(--color-work);
  color: #fff;
}

.phase-rest {
  background-color: var(--color-rest);
  color: #fff;
}

.canvas-container {
  width: 128px;
  height: 128px;
  background-color: var(--color-dark);
  border: 3px solid var(--color-dark);
  display: flex;
  align-items: center;
  justify-content: center;
}

#pixel-canvas {
  image-rendering: pixelated;
  width: 128px;
  height: 128px;
}

.countdown-box {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.countdown-digits {
  font-size: 56px;
  font-weight: 900;
  line-height: 1;
  color: var(--color-accent);
  text-shadow: 3px 3px 0px var(--color-dark);
}

.unit-label {
  font-size: 13px;
  letter-spacing: 2px;
  margin-top: 4px;
  opacity: 0.8;
}

.trophy-badge {
  font-size: 32px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-dark);
}

.complete-text {
  font-size: 26px;
  text-align: center;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-dark);
}

.complete-subtext {
  font-size: 15px;
  text-align: center;
  opacity: 0.9;
}

.controls-bar {
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}

.pixel-btn {
  flex: 1 1 calc(33.333% - 10px);
  min-width: 90px;
  padding: 12px 8px;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  border: 3px solid var(--color-dark);
  box-shadow: 3px 3px 0px var(--color-dark);
  transition: transform 0.05s ease, box-shadow 0.05s ease;
  outline: none;
  text-align: center;
}

.pixel-btn:hover {
  filter: brightness(1.15);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-text);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 0px 0px 0px var(--color-dark);
}

.btn-primary {
  background-color: var(--color-accent);
  color: var(--color-dark);
}

.btn-secondary {
  background-color: var(--color-work);
  color: #fff;
}

.btn-outline {
  background-color: var(--color-dark);
  color: var(--color-text);
}

.timer-footer {
  text-align: center;
}

.hint {
  font-size: 13px;
  opacity: 0.7;
}

@media (max-width: 380px) {
  .countdown-digits {
    font-size: 46px;
  }
  .title {
    font-size: 24px;
  }
  .pixel-btn {
    font-size: 14px;
    padding: 10px 4px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_SETS = 3;
  const WORK_SECONDS = 40;
  const REST_SECONDS = 20;

  let currentSet = 1;
  let currentPhase = 'Work'; // 'Work' | 'Rest'
  let timeLeft = WORK_SECONDS;
  let isRunning = false;
  let timerInterval = null;
  let isComplete = false;
  let animTick = 0;

  // DOM Elements
  const activeView = document.getElementById('active-view');
  const completeView = document.getElementById('complete-view');
  const setDisplay = document.getElementById('set-display');
  const phaseDisplay = document.getElementById('phase-display');
  const countdownDisplay = document.getElementById('countdown-display');
  const btnToggle = document.getElementById('btn-toggle');
  const btnSkip = document.getElementById('btn-skip');
  const btnReset = document.getElementById('btn-reset');
  const canvas = document.getElementById('pixel-canvas');
  const ctx = canvas.getContext('2d');

  function drawPixelArt() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const scale = 8;
    const offsetBounce = isRunning && currentPhase === 'Work' ? (Math.floor(animTick / 2) % 2) * 2 : 0;
    const restOffset = isRunning && currentPhase === 'Rest' ? (Math.floor(animTick / 4) % 2) : 0;

    const colorPrimary = currentPhase === 'Work' ? '#ff5964' : '#35a7ff';
    const colorSkin = '#f8c537';
    const colorDark = '#0f0f15';

    function drawPixel(x, y, color) {
      ctx.fillStyle = color;
      ctx.fillRect(x * scale, (y + offsetBounce + restOffset) * scale, scale, scale);
    }

    // Head
    for (let x = 6; x <= 9; x++) {
      for (let y = 2; y <= 5; y++) {
        drawPixel(x, y, colorSkin);
      }
    }
    // Eyes
    drawPixel(7, 3, colorDark);
    drawPixel(9, 3, colorDark);

    // Torso
    for (let x = 6; x <= 9; x++) {
      for (let y = 6; y <= 9; y++) {
        drawPixel(x, y, colorPrimary);
      }
    }

    // Arms & Animation (Work = jumping jacks / lifting weights, Rest = relaxed)
    if (currentPhase === 'Work') {
      if (animTick % 2 === 0) {
        // Arms up
        drawPixel(5, 5, colorSkin);
        drawPixel(4, 4, colorSkin);
        drawPixel(10, 5, colorSkin);
        drawPixel(11, 4, colorSkin);
        // Dumbbells
        drawPixel(4, 3, colorDark);
        drawPixel(11, 3, colorDark);
        // Legs spread
        drawPixel(5, 10, colorDark);
        drawPixel(4, 11, colorDark);
        drawPixel(10, 10, colorDark);
        drawPixel(11, 11, colorDark);
      } else {
        // Arms middle
        drawPixel(5, 7, colorSkin);
        drawPixel(4, 8, colorSkin);
        drawPixel(10, 7, colorSkin);
        drawPixel(11, 8, colorSkin);
        // Dumbbells
        drawPixel(4, 9, colorDark);
        drawPixel(11, 9, colorDark);
        // Legs together
        drawPixel(7, 10, colorDark);
        drawPixel(7, 11, colorDark);
        drawPixel(8, 10, colorDark);
        drawPixel(8, 11, colorDark);
      }
    } else {
      // Rest phase relaxed pose
      drawPixel(5, 7, colorSkin);
      drawPixel(5, 8, colorSkin);
      drawPixel(10, 7, colorSkin);
      drawPixel(10, 8, colorSkin);
      drawPixel(7, 10, colorDark);
      drawPixel(7, 11, colorDark);
      drawPixel(8, 10, colorDark);
      drawPixel(8, 11, colorDark);
    }
  }

  function updateUI() {
    if (isComplete) {
      activeView.hidden = true;
      completeView.hidden = false;
      btnToggle.hidden = true;
      btnSkip.hidden = true;
      btnReset.textContent = 'RESTART';
      btnReset.focus();
      return;
    }

    activeView.hidden = false;
    completeView.hidden = true;
    btnToggle.hidden = false;
    btnSkip.hidden = false;
    btnReset.textContent = 'RESET';

    setDisplay.textContent = `SET ${currentSet} / ${TOTAL_SETS}`;
    phaseDisplay.textContent = currentPhase.toUpperCase();

    if (currentPhase === 'Work') {
      phaseDisplay.className = 'badge phase-work';
    } else {
      phaseDisplay.className = 'badge phase-rest';
    }

    countdownDisplay.textContent = timeLeft < 10 ? `0${timeLeft}` : `${timeLeft}`;
    btnToggle.textContent = isRunning ? 'PAUSE' : 'START';

    drawPixelArt();
  }

  function advancePhase() {
    if (currentPhase === 'Work') {
      currentPhase = 'Rest';
      timeLeft = REST_SECONDS;
    } else {
      if (currentSet < TOTAL_SETS) {
        currentSet++;
        currentPhase = 'Work';
        timeLeft = WORK_SECONDS;
      } else {
        finishWorkout();
        return;
      }
    }
    animTick = 0;
    updateUI();
  }

  function finishWorkout() {
    stopTimer();
    isComplete = true;
    updateUI();
  }

  function tick() {
    animTick++;
    if (timeLeft > 1) {
      timeLeft--;
      updateUI();
    } else {
      advancePhase();
    }
  }

  function startTimer() {
    if (isComplete) return;
    isRunning = true;
    updateUI();
    timerInterval = setInterval(tick, 1000);
  }

  function stopTimer() {
    isRunning = false;
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    updateUI();
  }

  function toggleTimer() {
    if (isRunning) {
      stopTimer();
    } else {
      startTimer();
    }
  }

  function skipPhase() {
    if (isComplete) return;
    advancePhase();
  }

  function resetTimer() {
    stopTimer();
    currentSet = 1;
    currentPhase = 'Work';
    timeLeft = WORK_SECONDS;
    isComplete = false;
    animTick = 0;
    updateUI();
    btnToggle.focus();
  }

  // Event Listeners
  btnToggle.addEventListener('click', toggleTimer);
  btnSkip.addEventListener('click', skipPhase);
  btnReset.addEventListener('click', resetTimer);

  // Keyboard Accessibility
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.code === 'Space') {
      e.preventDefault();
      if (!isComplete) toggleTimer();
    } else if (e.key === 's' || e.key === 'S') {
      e.preventDefault();
      if (!isComplete) skipPhase();
    } else if (e.key === 'r' || e.key === 'R') {
      e.preventDefault();
      resetTimer();
    }
  });

  // Initial Render
  updateUI();
});
